      "id": "consolidation-measurement-period-contingent-consideration-goodwill",
      "updatedAt": "2026-09-08",
      "topic": "合并财务报表",
      "difficulty": "高频易错",
      "question": "购买日后 12 个月内因购买日已存在情况的新证据调整或有对价，单体和合并分别怎么调？",
      "summary": "计量期调整在个别报表修正长投成本，在合并层面修正商誉；已带入的或有对价资产或负债不重复确认。",
      "conclusion": [
        "条件：购买日后12个月内取得购买日已存在情况的新证据，修正购买日暂定金额，作为购买日会计处理的调整。购买日后经营情况或股价变化引起的估值变动不属于此项；发现前期差错则另按第24章判断，不能仅因超过12个月排除纠错。",
        "报表衔接：个别报表先调整长投及相应或有对价资产、负债；合并时这些资产、负债已经带入，长投的调整通过抵销转为商誉调整。以下底稿分录仅表示增量，不再另作一遍相同资产或负债确认。"
      ],
      "reasoning": [
        "追加支付例（万元）：购买日暂估义务500，计量期内的新证据证明其购买日公允价值应为800，增加300。假设该收购形成商誉，无其他税项等影响。个别与合并底稿分别见前两笔分录。",
        "收回对价例（独立情形，万元）：同样符合计量期条件，应收补偿权的购买日公允价值增加300。假设原商誉足够冲减，无其他税项等影响，分别见后两笔分录。",
        "合并整体增量：追加支付为借商誉、贷金融负债300；补偿权为借金融资产、贷商誉300。这是个别与底稿两步合计的效果，不另执行。商誉不足冲减或原为廉价购买时，按复核后的购买法结果处理，不产生负商誉。"
      ],
