      "conclusion": [],
      "reasoning": [
        "例如作出重大专门化改造或经营决策，改变继续使用资产的经济动机；须同时满足“可控、重大、影响选择权判断”，不是任何自主行动都触发重估。",
        "单纯市场租金等外部变化通常不单独触发上述重新评估；续租或终止选择权的实际行使与原判断不一致等导致租赁期变化，也须重新确定付款额。",
        "租赁期或购买选择权评估改变后的折现率规则，见“承租人重新计量租赁负债”卡。",
        "依据：《企业会计准则第21号——租赁》第15、25条（https://kjs.mof.gov.cn/zt/kjzzss/kuaijizhunzeshishi/201910/t20191028_3411190.htm）。"
      ],
