      "id": "lease-net-investment-unguaranteed-residual-value",
      "updatedAt": "2026-09-08",
      "topic": "租赁",
      "difficulty": "高频基础",
      "question": "未担保余值是什么？如何折现并计入租赁投资净额？",
      "summary": "未担保余值是期末余值中，出租人无法保证实现，或仅由与出租人有关的一方担保的部分。",
      "conclusion": [],
      "reasoning": [
        "未担保余值是出租人预计从资产残值收回的金额，不是承租人欠付的租金；“有人担保”仍须核对担保方与出租人的关系及适用条件。",
        "例：设备公允价值100万元，合同租金合计90万元，期末预计售价10万元且无人保底，这10万元属于未担保余值。90＋10是未折现回收额，不能据此证明净投资为100万元。",
        "按租赁内含利率折现：净投资＝尚未收到的租赁收款额现值＋未担保余值现值；未实现融资收益＝上述未来回收名义总额－净投资。",
        "例：3年后未担保余值10万元，内含利率5%，现值＝10÷1.05³≈8.64万元；差额约1.36万元是未实现融资收益的一部分。",
        "完整初始分录见“出租人融资租赁在租赁期开始日的分录”卡。",
        "依据：《企业会计准则第21号——租赁》第17、19、38条（https://kjs.mof.gov.cn/zt/kjzzss/kuaijizhunzeshishi/201910/t20191028_3411190.htm）。"
      ],
      "memory": [],
      "pitfalls": [],
