      "summary": "租赁期开始日终止确认租赁资产，以租赁投资净额确认应收融资租赁款；未实现融资收益用于抵减名义应收总额。",
      "conclusion": [],
      "reasoning": [
        "普通出租人按内含利率计量时，净投资对应资产公允价值及初始直接费用，并扣除租赁期开始日或之前已收到的租赁收款额；不能把已经收到的租金再列未来应收。生产商或经销商的费用处理见对应专卡。",
        "下例无预收款，资产账面价值与公允价值均为100万元，初始直接费用2万元当日支付；未来租赁收款额110万元、未担保余值10万元，按内含利率计算净投资102万元，未实现融资收益18万元。",
        "出租人使用“未实现融资收益”，承租人租赁负债明细使用“未确认融资费用”，两者不能混写。"
      ],
