      "question": "租赁付款额的五项内容是什么？恢复义务预计负债为什么不计入租赁负债？",
      "summary": "租赁负债只纳入尚未支付的租赁付款额现值；符合条件的恢复义务另计预计负债，通常计入使用权资产成本。",
      "conclusion": [],
      "reasoning": [
        "| 租赁付款额组成 | 纳入条件或金额 |\n| --- | --- |\n| 固定及实质固定付款额 | 扣除租赁激励 |\n| 指数或比率挂钩可变付款额 | 取租赁期开始日参数，详见可变付款额卡 |\n| 购买选择权行权价 | 合理确定将行使 |\n| 终止租赁付款 | 租赁期反映将行使终止选择权 |\n| 承租人担保余值 | 预计需支付金额，不是担保上限 |",
        "担保例：保证期末残值20万元，预计实际残值18万元，纳入付款额2万元；预计残值22万元，则预计付款为0。",
        "使用权资产初始成本＝租赁负债＋开始日或之前已付款（扣除已享受激励）＋初始直接费用＋符合条件的恢复成本。已在负债计量中扣除的激励，不再重复扣除。",
        "拆除装修和恢复场地预计支出10万元，满足或有事项准则条件时按现值确认预计负债。若该成本属于为生产存货而发生的，应适用存货准则，不能一概计入使用权资产。"
      ],
