      "question": "生产商或经销商出租人的融资租赁，为什么要同时确认销售收入、销售成本和融资收益？初始直接费用怎么处理？",
      "summary": "生产商或经销商融资出租产品，在租赁期开始日确认销售损益，后续再确认融资收益；取得融资租赁发生的成本当期费用化。",
      "conclusion": [],
      "reasoning": [
        "| 租赁期开始日项目 | 计量 |\n| --- | --- |\n| 销售收入 | 资产公允价值与租赁收款额按市场利率折现的现值孰低 |\n| 销售成本 | 资产账面价值−未担保余值现值 |\n| 为取得融资租赁发生的成本 | 当期损益，本例使用销售费用；不计入净投资 |",
        "例：公允价值100万元、收款额市场利率现值98万元、资产成本80万元、未担保余值现值2万元、取得合同成本1万元：收入98，成本78，费用1，初始损益19万元。",
        "另一下列分录示例无未担保余值，假设资产公允价值不低于405.73万元，无预收租金，租赁收款额450万元、市场利率现值405.73万元，存货成本320万元、佣金2万元，初始损益83.73万元。",
        "后续收款及计息统一见“应收融资租赁款后续计息”卡。普通出租人初始直接费用计入净投资的规则不能直接套用本卡。",
        "依据：财政部《企业会计准则第21号——租赁》第37—39、42条（https://kjs.mof.gov.cn/zt/kjzzss/kuaijizhunzeshishi/201910/t20191028_3411190.htm）。"
      ],
