      "question": "哪些房地产属于投资性房地产？",
      "summary": "投资性房地产包括已出租土地使用权、持有并准备增值后转让的土地使用权和已出租建筑物。",
      "conclusion": [
        "空置或在建建筑物已有董事会等正式书面决议明确用于经营出租、且持有意图短期内不变的，可视为投资性房地产。",
        "计划出租但尚未出租的土地使用权，不直接适用上述建筑物例外；自用房地产和作为存货持有的房地产不属于投资性房地产。"
      ],
