        "采用公允价值模式，须所在地有活跃房地产交易市场，且能取得同类或类似房地产市场价格等信息，持续可靠估计公允价值。",
        "解释第18号例外：浮动收费法下作为基础项目持有的投资性房地产，可与其余投资性房地产分别选择模式；该部分内部须统一，满足公允价值条件后才能选用，选用后不得转回。原已采用公允价值的，该部分应全部采用公允价值。"
