      "id": "investment-property-entry-and-disposal-logic",
      "updatedAt": "2026-09-06",
      "topic": "投资性房地产",
      "difficulty": "高频提高",
      "question": "投资性房地产出售时如何结转成本和累计收益？",
      "summary": "出售投资性房地产，确认其他业务收入并结转其他业务成本；转为自用不属于出售。",
      "conclusion": [
        "公允价值模式处置时，成本和公允价值变动明细一并结转；累计公允价值变动损益及转入时形成的其他综合收益转入其他业务成本。",
        "成本模式处置时，注销原价及累计折旧、摊销、减值准备，以净额结转成本。"
      ],
      "reasoning": [
        "例：成本明细 1,000、累计公允价值变动收益 120、转入时其他综合收益 80。处置前账面价值为 1,120；先全额转成本，再重分类累计收益。公允价值变动损益的重分类不改变处置当期利润总额；其他综合收益结转影响处置当期损益。"
      ],
      "memory": [],
      "pitfalls": [
        "非投房转入时的增值计入其他综合收益，跌价已计入损益；不能虚设一个对称的“转入时其他综合收益损失”。"
      ],
