      "id": "income-tax-business-combination-dta-after-acquisition",
      "updatedAt": "2026-09-08",
      "topic": "所得税费用",
      "difficulty": "高频易错",
      "question": "企业合并购买日后补确认递延所得税资产时，为什么可能冲减商誉？",
      "summary": "购买日未满足条件的递延所得税资产，后续确认须区分12个月内证明购买日情况的证据与其他情形。",
      "conclusion": [],
      "reasoning": [
        "购买日未满足确认条件，后在12个月内取得证明购买日相关情况已存在的新信息或进一步证据，且预期可抵扣差异的经济利益能够实现：确认递延所得税资产，先冲减商誉，不足部分计入所得税费用。",
        "其他后续满足确认条件的情形：确认递延所得税资产并计入当期损益，不调整商誉。属于前期差错的，另按差错更正规则处理。",
        "购买利得与补确认税收利益分开：前者经复核计营业外收入；上述冲减商誉不足的差额贷记所得税费用。"
      ],
