        "| 权益工具计量条件 | 确认金额 |\n| --- | --- |\n| 权益公允价值可靠 | 权益工具公允价值 |\n| 权益公允价值不能可靠计量 | 所清偿债务公允价值 |\n\n旧债账面价值减权益确认金额计投资收益；面值计股本，其余计股本溢价，不能因债务公允价值更易取得就跳过权益公允价值。",
