      "question": "债权人以债权换取股权后，交易性金融资产、其他权益工具投资和长期股权投资如何分类、计量并编制分录？",
      "summary": "债权换股先判投资性质；金融资产与长投的初始计量、交易费用及日初差额不同，旧债权须满足终止确认条件。",
      "conclusion": [
        "本卡比较未形成企业合并、非权益性交易且旧债权满足终止确认条件的情形；取得控制并构成业务时，转按企业合并等规则。重大影响或共同控制下的长投，与按金融工具准则处理的股权分开判断。"
      ],
      "reasoning": [
        "设应收余额1 000、坏账准备100，账面价值B＝900；放弃债权公允价值D＝920，取得股份公允价值F＝950，另付直接交易费用30（金额单位一致）。假设D为本例交易价格，无其他交易组成部分；金融资产例中的F有相同资产活跃市场报价或仅使用可观察市场数据的估值依据。",
        "| 取得投资 | 初始金额 | 当期投资收益（净额） |\n| --- | --- | --- |\n| 以公允价值计量且变动进损益的金融资产 | F＝950；费用30计损益 | D－B＋(F－D)－30＝20 |\n| 符合条件并在初始确认时指定的非交易性其他权益工具投资 | F＋30＝980 | D－B＋(F－D)＝50 |\n| 联营或合营长投 | D＋30＝950 | D－B＝20 |",
        "金融资产日初差额F－D只有符合上述报价或仅使用可观察数据条件才立即计损益。采用其他方式确定公允价值时，应调整初始确认金额以递延差额，后续依金融工具准则确认；不能因题目未说明输入值就默认满足条件。具体日初差额规则见金融工具章。",
        "本表长投金额是初始投资成本；采用权益法后，还须比较应享有被投资单位可辨认净资产公允价值份额，符合条件的初始成本调整另按长投准则。其他权益工具投资是债权人资产，与债务人列报的其他权益工具不是同一科目。"
      ],
      "memory": [],
