      "updatedAt": "2026-09-07",
      "topic": "债务重组",
      "difficulty": "高频综合",
      "question": "债权人修改其他条款：如何区分终止确认与未终止确认？",
      "summary": "先判断原债权是否终止确认：终止确认则确认新资产；未终止确认则重算原债权账面余额，并另行处理信用减值。",
      "conclusion": [
        "合同收款权利终止，或资产转移满足终止确认条件时，注销原债权并按金融工具准则确认新资产；不得直接套用债务人的10%测试作为债权人的唯一判断标准。",
        "终止确认：新债权按公允价值初始计量，按分类处理交易费用；与旧债权账面价值的差额计入投资收益。后续按新资产分类处理，摊余成本债权采用新实际利率。",
        "未终止确认：修改后合同现金流按原实际利率折现，重算账面余额；修改差额计入投资收益。相关修改成本或费用调整账面价值，在剩余期限摊销。"
      ],
      "reasoning": [
        "【对照例】旧债权成本及账面余额均为100，无利息调整；为突出条款修改，例题暂不列减值准备及交易费用。修改后一年收80，旧实际利率5%。",
        "未终止确认：余额80÷1.05＝76.19，修改损失23.81；次年利息76.19×5%＝3.81，余额回升至80并收款。",
        "终止确认且新债权公允价值76、按摊余成本计量：确认新债权76，损失24；新实际利率80÷76－1＝5.263%，次年利息4，到期收80。",
        "例题已分别给定终止确认结论，不能仅凭收款100变80推导结论。实际重组须另行评估信用减值；有损失准备时，账面余额不等于账面价值，计息还须区分是否已发生信用减值。"
      ],
      "memory": [],
      "pitfalls": [
        "原实际利率有特定口径：购买或源生的已发生信用减值资产使用经信用调整的实际利率；适用套期会计准则第23条时使用其重新计算的实际利率。",
        "条款修改损益与预期信用损失分别核算；以公允价值计量的债权还需按所属分类处理公允价值变动及其他综合收益，不能直接照搬本例摊余成本结果。"
      ],
